import matplotlib.pyplot as plt
import numpy as np
from scipy.signal import find_peaks

fs = 125_000 #Hz

def find_and_plot_envelope_edge_peaks(envelope_edge, ax=None):
    """Find peaks in an envelope-edge signal and plot them as red dots."""
    envelope_edge = np.asarray(envelope_edge, dtype=float).ravel()
    if ax is None:
        ax = plt.gca()
    if envelope_edge.size == 0:
        return np.array([], dtype=int)

    max_strength = -float(np.min(envelope_edge))

    if max_strength <= 0.0:
        return np.array([], dtype=int)

    peak_kwargs = {
        "distance": 5,
        "prominence": 0.01 * float(np.std(envelope_edge)),
        "height": 0.3 * max_strength,
    }

    peak_indices, _ = find_peaks(-envelope_edge, **peak_kwargs)

    # Fallback for difficult/noisy traces where strict thresholds find nothing.
    if peak_indices.size == 0:
        peak_indices, _ = find_peaks(-envelope_edge, distance=3, height=0.3 * max_strength)

    ax.plot(peak_indices, envelope_edge[peak_indices], "ro", label="Peaks")
    return peak_indices

def plot_idx_line(idx, color="red", label=None):
    """Plot one vertical line at the specified index."""
    plt.axvline(x=idx, color=color, linestyle="--", label=label)

